import {transitionExampleState} from './transition-example.js?v=0.31.0';
import {selectCareer,applyGuidePay,createPlanActions,toggleGuideFamily,toggleGuidePath} from './guide-state.js?v=0.31.0';
import {occupationById} from './occupation-data.js?v=0.31.0';
import {salaryAtStage,formatSalary} from './salary-progression.js?v=0.31.0';
import {lifestyleRoom} from './lifestyle-story.js?v=0.31.0';
import {clinicalTrainingTimeline,professionalCostPanel} from './education-evidence-ui.js?v=0.31.0';
import {explorationHistoryPanel} from './guide-ui.js?v=0.31.0';
import {escapeHTML as h} from './model.js?v=0.31.0';
export function careerSwitchBeforeState(){const s=transitionExampleState();Object.assign(s.actions.find(a=>a.id==='guide-graphic-design-try'),{done:true,dueDate:'2026-11-03',notice:'I enjoyed the biology poster, but talking about patient care made me want to explore medicine. Keep design as an earlier interest.'});return s;}
export function careerSwitchExampleState(){const s=careerSwitchBeforeState();toggleGuideFamily(s,'creative');toggleGuideFamily(s,'health');toggleGuidePath(s,'medicines-nutrition');s.guide.taskInterests=['work:physician'];selectCareer(s,'physician');s.guide.preparation=occupationById('physician').finance.educationRoutes.routes[0];applyGuidePay(s);s.guide.salaryPicked=true;createPlanActions(s);return s;}
export function careerSwitchExamplePage(){const before=careerSwitchBeforeState(),after=careerSwitchExampleState(),scenarios=[{id:'graphic-design',stage:'entry',title:'Earlier · graphic design',basis:'Regional entry-pay proxy',inputs:before.finance.lifestyle},{id:'physician',stage:'residency',title:'Next · paid residency',basis:'Dell Med first-year resident example',inputs:after.finance.lifestyle},{id:'physician',stage:'entry',title:'Later · qualified practice',basis:'Family medicine · regional entry-pay proxy',inputs:{...after.finance.lifestyle,gross:String(salaryAtStage('physician','entry'))}}];const old=after.actions.find(a=>a.id==='guide-graphic-design-try');return `<div class="page-intro"><div><span class="eyebrow">A FICTIONAL STUDENT · CHANGING DIRECTION</span><h1>From design to medicine.</h1><p>A new focus. Earlier work stays with you.</p></div></div><p>Read-only example. Your own answers and plan stay yours.</p><section class="personal-plan-section"><h2>Same Austin life. Different pay stages.</h2><p>One adult. A rental of their own, a used car, and about one dinner out a week.</p><div class="switch-scenarios">${scenarios.map(c=>{const room=lifestyleRoom(c.inputs);return `<article class="switch-scenario switch-${room.key}"><h3>${h(c.title)}</h3><strong class="switch-pay">${formatSalary(salaryAtStage(c.id,c.stage))}<span> / year before tax</span></strong><p>${h(c.basis)}</p><h3>${h(room.title)}</h3><p>${h(room.copy)}</p><a href="#/salary/${c.id}/${c.stage}?from=career">Picture this salary →</a></article>`;}).join('')}</div><p><strong>This comparison is before any student-loan payments.</strong> Add borrowing costs when known. The spending choices stay the same; more pay does not automatically buy a bigger home.</p><details class="more-info"><summary>How these numbers are used</summary><p>Starting pay is a Texas Workforce Commission lower-paid-third proxy, not measured first-job pay. Residency uses a published 2026–27 employer example. Taxes and lifestyle are estimates in today’s dollars. No income from medical practice is assumed during college or medical school.</p><p><a href="#/source-review">Financial sources & assumptions →</a></p></details></section><section class="personal-plan-section"><h2>A different education route.</h2><p><strong>College → medical school → paid residency.</strong> This example explores family medicine.</p>${clinicalTrainingTimeline('physician')}${professionalCostPanel('physician')}<p>No specific college major guarantees admission to medical school.</p></section><section class="personal-plan-section"><h2>Design is still part of the story.</h2><article class="personal-action"><h3>${h(old.title)}</h3><p><strong>Completed · target date ${h(old.dueDate)}</strong></p><p>${h(old.notice)}</p></article><p>All 30 earlier answers, priorities, activity notes, and unfinished design steps are kept. Graphic design remains a saved alternative.</p></section>${explorationHistoryPanel(after,{readOnly:true})}<section class="personal-plan-section"><h2>Three new steps for medicine.</h2>${after.actions.filter(a=>a.careerId==='physician').map(a=>`<article class="personal-action"><h3>${h(a.title)}</h3><p>${h(a.detail)}</p><p><strong>Ready to try.</strong> Earlier completed activities stay completed.</p></article>`).join('')}<p><a href="#/career/physician">Explore physician education, work & pay →</a></p></section><details class="more-info"><summary>What we tested</summary><p>An existing fictional design draft was taken through health interests, medicine tasks, medical preparation, residency pay, and a new personal plan. We checked later practice pay, switching back to design and returning to medicine, reopening, full-draft restoration, and real plan exports.</p><p>Regression checks also cover debt, manual take-home overrides, retirement limits, and keeping earlier tuition budgets separate. These checks test the application’s behavior, not the likelihood of admission, job success, or future pay.</p></details><p><a href="#/student-examples/next-step">See the earlier exploration-to-design journey →</a></p>`;}
